import React, { useState } from "react";
import DeckForm from "./components/DeckForm";
import DeckAnalysisInteractive from "./components/DeckAnalysisInteractive";
import { DeckAnalysisResponse } from "./types/lorcanaDeck";

const App: React.FC = () => {
  const [analysis, setAnalysis] = useState<DeckAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (deck:any[])=>{
    setLoading(true); setError("");
    try{
      const res = await fetch("http://localhost:3000/analyzeDeck",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({deck})});
      const data = await res.json();
      if(res.ok)setAnalysis(data); else setError(data.error||"Erro desconhecido");
    }catch(err:any){setError(err.message);}finally{setLoading(false);}
  }

  return (
    <div style={{padding:"20px"}}>
      <h1>Lorcana Deck Analyzer - Full Stack</h1>
      <DeckForm onSubmit={handleSubmit}/>
      {loading && <p>Carregando análise...</p>}
      {error && <p style={{color:"red"}}>{error}</p>}
      {analysis && <DeckAnalysisInteractive analysis={analysis}/>}
    </div>
  );
}

export default App;
